// Some portions generated by Claude
import { useDeferredValue, useId, useMemo, useState, type KeyboardEvent, type RefObject } from "react";
import { findNodes } from "./graph-find.ts";
import { compactTerm } from "./graph-terms.ts";
import type { GraphNode } from "./graph-types.ts";
import { Icon } from "./icons.tsx";

export type FindFieldProps = {
  /** The nodes on the canvas. */
  nodes: readonly GraphNode[];
  busy: boolean;
  inputRef: RefObject<HTMLInputElement | null>;
  /** Shows the node's details and brings it into view. */
  onReveal: (nodeId: string) => void;
  /** Adds the repository's resources that match the term to the graph. */
  onSearchRepository: (term: string) => void;
};

type Option = { kind: "node"; node: GraphNode; detail: string } | { kind: "repository" };

function optionClass(option: Option, active: boolean) {
  const classes = active ? ["is-active"] : [];
  if (option.kind === "repository") classes.push("is-repository-search");
  return classes.join(" ");
}

/**
 * The toolbar's find field: the loaded nodes that match as you type (Enter shows the first), and as the last choice
 * a search of the whole repository that adds what it finds.
 */
export function FindField({ nodes, busy, inputRef, onReveal, onSearchRepository }: FindFieldProps) {
  const listId = useId();
  const [term, setTerm] = useState("");
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const deferredTerm = useDeferredValue(term);
  const options = useMemo<Option[]>(() => {
    if (!deferredTerm.trim()) return [];
    const found: Option[] = findNodes(nodes, deferredTerm).map((match) => ({
      kind: "node",
      node: match.node,
      detail: match.in === "iri" ? compactTerm(match.node.id, 48) : (match.node.types?.[0]?.label ?? ""),
    }));
    return [...found, { kind: "repository" }];
  }, [nodes, deferredTerm]);
  const shown = open && options.length > 0;
  const current = Math.min(active, options.length - 1);

  const choose = (option: Option | undefined) => {
    if (!option) return;
    if (option.kind === "node") onReveal(option.node.id);
    else if (!busy && term.trim()) onSearchRepository(term.trim());
    setOpen(false);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      if (!options.length) return;
      setOpen(true);
      const step = event.key === "ArrowDown" ? 1 : -1;
      setActive(shown ? (current + step + options.length) % options.length : 0);
    } else if (event.key === "Enter") {
      event.preventDefault();
      choose(options[shown ? current : 0]);
    } else if (event.key === "Escape") {
      if (shown) {
        event.stopPropagation();
        setOpen(false);
      } else if (term) {
        event.stopPropagation();
        setTerm("");
      }
    }
  };

  return (
    <div className="graph-find" role="search">
      <Icon name="search" />
      <input
        ref={inputRef}
        type="search"
        role="combobox"
        aria-label="Find a node, or search the repository"
        aria-keyshortcuts="/"
        title="Find a node (/)"
        aria-autocomplete="list"
        aria-expanded={shown}
        aria-controls={listId}
        aria-activedescendant={shown ? `${listId}-${current}` : undefined}
        placeholder="Find"
        value={term}
        onChange={(event) => {
          setTerm(event.target.value);
          setActive(0);
          setOpen(true);
        }}
        onFocus={() => setOpen(true)}
        onBlur={() => setOpen(false)}
        onKeyDown={onKeyDown}
      />
      {shown ? (
        <ul id={listId} role="listbox" className="graph-find-results" aria-label="Matches">
          {options.map((option, index) => (
            <li
              key={option.kind === "node" ? option.node.id : "repository"}
              id={`${listId}-${index}`}
              role="option"
              aria-selected={index === current}
              className={optionClass(option, index === current)}
              onMouseDown={(event) => event.preventDefault()}
              onMouseEnter={() => setActive(index)}
              onClick={() => choose(option)}
            >
              {option.kind === "node" ? (
                <>
                  <span className="graph-find-label">{option.node.label}</span>
                  {option.detail ? <small>{option.detail}</small> : null}
                </>
              ) : (
                <span className="graph-find-label">
                  <Icon name="search" />
                  Search the repository for “{deferredTerm.trim()}”
                </span>
              )}
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  );
}
